// eslint-disable-next-line @typescript-eslint/no-redeclare
export const AccountStage = {
  Trialing: 2,
  Subscribing: 3,
  Cancelling: 4,
  Expired: 5,
  /** Trial Expired */
  TrialExpired: 6,
  /** Past Due */
  PastDue: 7,
  /** Cancelling Trial */
  CancellingTrial: 8,
  Paused: 9,
  Created: 10,
} as const;

